sql_query:
SELECT v.VAR_id 
FROM varInfo v 
WHERE v.gene_name = 'NEK1' AND v.HighImpact = 1 AND v.CADDphred > 20;

SELECT v.*
FROM varInfo v
WHERE v.gene_name = 'NEK1' AND v.HighImpact = 1 AND v.CADDphred > 20;

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT < 0.1;

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'D';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT AVG(AF) 
FROM varInfo 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF
FROM varInfo
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT SUM(CASE WHEN T1.pheno = 'CASE' THEN T2.AF ELSE 0 END) - SUM(CASE WHEN T1.pheno = 'CONTROL' THEN T2.AF ELSE 0 END) AS allele_difference
FROM pheno AS T1
JOIN varInfo AS T2 ON T1.IID = T2.VAR_id;

SELECT EXISTS (
    SELECT 1 
    FROM varInfo 
    WHERE VAR_id = 100 AND HighImpact IS NOT NULL AND ModerateImpact IS NOT NULL AND Synonymous IS NOT NULL
);

SELECT DISTINCT VAR_id 
FROM varInfo 
ORDER BY CADDphred DESC, PolyPhen DESC, SIFT DESC;

SELECT DISTINCT VAR_id 
FROM varInfo 
WHERE Synonymous = '1' AND HighImpact = '1';

SELECT DISTINCT VAR_id 
FROM varInfo 
WHERE Synonymous = '1' AND HighImpact = '1';

SELECT AVG(AF) AS MAF 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND ModerateImpact;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 'TRUE';
